#!/usr/bin/env python3
"""Behavioral proof for exact owner/generation startup and frozen source writes."""
import argparse,hashlib,importlib.util,json,pathlib,re,subprocess,tempfile
p=argparse.ArgumentParser();p.add_argument('--java-home',required=True,type=pathlib.Path);p.add_argument('--json-jar',required=True,type=pathlib.Path);p.add_argument('--output',required=True,type=pathlib.Path);a=p.parse_args();a.output.parent.mkdir(parents=True,exist_ok=True)
r=pathlib.Path(__file__).resolve().parents[2];d=r/'app/src/main/java/local/pocketchat';here=pathlib.Path(__file__).parent
spec=importlib.util.spec_from_file_location('blocks',r/'tools/gecko/run_network_core_host.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
native=(d/'NativeNetwork.java').read_text();provider=(d/'NetworkUiProvider.java').read_text();service=(d/'NetworkTransportService.java').read_text();selection=(d/'NetworkSourceSelection.java').read_text()
methods={'RECEIPT':'  static final class ExitRouteReceipt ','CONFIGURATION_SOURCES':'  static final class ConfigurationSources ','CONFIGURATION_OPERATION':'  synchronized void configurationOperation(','RUN_CONFIGURATION':'  void runConfigurationOperation(','PUBLISH_SOURCE':'  void publishStartupSource(','ADMISSION':'  NetworkHealthPolicy.Admission connectionAdmission(', 'SCHEDULE_PROOF':'  synchronized void scheduleProofRefresh(', 'SOURCE_CACHE_MATCHES':'  static boolean sourceCacheMatches(', 'SUBSCRIBED_EXIT':'  static boolean subscribedExit(', 'SOURCE_META':'  JSONObject sourceMeta(', 'AUTHORITY_CURRENT':'  boolean authoritySourcesCurrent('}
fragments={key:m.block(native,value) for key,value in methods.items()};fragments['ACTIVE_MATCHES']=m.block(selection,'    boolean matches(Map<String,byte[]> expected)');fragments['ACTIVE_RESTORE']=m.block(selection,'    void restoreBefore(');fragments['ACTIVE_ROLLBACK']=m.block(selection,'    void rollback(');fragments['SELECT_POLICY']=m.block((d/'EnvironmentSpecRuntime.java').read_text(),'  static String selectNetworkApplicationPolicy(');fragments['SERVICE_GUARD']=m.block(service,'  void guardedChange(');fragments['AUTHORITY_RECORDS']=re.search(r'static final String\[\] RECORDS=\{[^;]+;',selection).group(0)
for key,signature in {'TASK_IDLE':'  static boolean taskIdle(', 'NATIVE_BUSY':'  static boolean nativeWorkBusy(', 'NATIVE_STATIC_EVENT':'  static void nativeWorkChanged(', 'NATIVE_REFRESH':'  void refreshNativeWork('}.items():fragments[key]=m.block(provider,signature)
source=(here/'ConfigurationHost.java.in').read_text()
for key,value in fragments.items():source=source.replace('@'+key+'@',value)
production=[d/x for x in ('EnvironmentSpec.java','NetworkApplicationReceipt.java','NetworkCoreApplication.java','NetworkApplyCoordinator.java','NetworkHealthPolicy.java','TaskGuardSnapshot.java','Sha256.java','J.java')]
inputs=[*production,d/'NativeNetwork.java',d/'NetworkTransportService.java',d/'NetworkSourceSelection.java',d/'EnvironmentSpecRuntime.java',d/'NetworkUiProvider.java',here/'ConfigurationHost.java.in',pathlib.Path(__file__),*sorted((here/'adapters').rglob('*.java'))]
input_hashes={str(x.relative_to(r)):hashlib.sha256(x.read_bytes()).hexdigest() for x in inputs}
with tempfile.TemporaryDirectory(prefix='network-configuration-host-') as temp:
 t=pathlib.Path(temp);generated=t/'ConfigurationHost.java';generated.write_text(source);classes=t/'classes';classes.mkdir();files=[*production,generated,*sorted((here/'adapters').rglob('*.java'))]
 compile_run=subprocess.run([str(a.java_home/'bin/javac'),'-J-XX:ActiveProcessorCount=2','-encoding','UTF-8','-cp',str(a.json_jar),'-d',str(classes),*map(str,files)],capture_output=True,text=True)
 a.output.with_suffix('.compile.stdout.log').write_text(compile_run.stdout);a.output.with_suffix('.compile.stderr.log').write_text(compile_run.stderr);compile_run.check_returncode()
 run=subprocess.run([str(a.java_home/'bin/java'),'-XX:ActiveProcessorCount=2','-cp',str(classes)+':'+str(a.json_jar),'local.pocketchat.ConfigurationHost'],capture_output=True,text=True)
 a.output.with_suffix('.stdout.log').write_text(run.stdout);a.output.with_suffix('.stderr.log').write_text(run.stderr);run.check_returncode()
 result=json.loads(run.stdout);assert result['passed']==len(result['checks']) and all(x['pass'] for x in result['checks'])
assert all(hashlib.sha256((r/name).read_bytes()).hexdigest()==digest for name,digest in input_hashes.items()),'Executed source inputs changed during host run'
result.update(executionInputsUnchanged=True,sourceCommit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=r,text=True).strip(),sourceDirty=bool(subprocess.check_output(['git','status','--porcelain'],cwd=r,text=True)),sourceSha256=input_hashes,methodsSha256={k:hashlib.sha256(v.encode()).hexdigest() for k,v in fragments.items()})
a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'status':result['status'],'passed':result['passed'],'report':str(a.output)}))
